<script>
 import {untrack} from 'svelte';import {asset} from '../studio.svelte';import {editor} from '../stores/editor.svelte';import {tasks} from '../stores/tasks.svelte';import {selectVersion,currentEditorBusy} from '../services/editor.js';import {activeVersion,versionLabel,versionProperties} from '../lib/editor-version.ts';
 let current=$state(null),key='',pending=$state(false),taskId=$state(null),desired=null;const a=$derived(asset());const busy=$derived(pending||currentEditorBusy()||taskId&&['queued','running'].includes(tasks.byId[taskId]?.state));
 $effect(()=>{const value=a,signature=value?JSON.stringify([value.id,value.generatedBase,value.edit]):'';if(signature!==key){key=signature;current=activeVersion(value);untrack(()=>{editor.versionId=current;const saved=versionProperties(value);editor.ratio=saved.ratio;Object.assign(editor.properties,saved.properties);});}});
 $effect(()=>{const task=tasks.byId[taskId];if(task?.state==='done'){current=desired;untrack(()=>editor.versionId=current);}else if(task&&['failed','partial','cancelled'].includes(task.state))current=activeVersion(a);});
 async function choose(id){if(busy||current===id)return;desired=id;pending=true;try{const result=await selectVersion(id);taskId=result?.task?.id||null;}finally{pending=false;}}
 const title=version=>JSON.stringify(version.generation?.operations||version.generation?.plan?.steps||version.edit).slice(0,400);
</script>
<nav class="version-bar" aria-label="版本条"><button class:current={current===null} aria-current={current===null?'step':undefined} disabled={!!busy} onclick={()=>choose(null)} title="原始图片，不删除历史版本">原图{#if current===null}<i></i>{/if}</button>{#each a?.versions||[] as version,index (version.id)}<span aria-hidden="true">→</span><button class:current={current===version.id} aria-current={current===version.id?'step':undefined} disabled={!!busy} onclick={()=>choose(version.id)} title={title(version)}>{versionLabel(version,index)}{#if current===version.id}<i></i>{/if}</button>{/each}</nav>
<style>.version-bar{display:flex;align-items:center;gap:8px;height:40px;min-height:40px;flex-shrink:0;overflow-x:auto;padding:0 12px;border-top:1px solid var(--border);background:var(--bg-elev);font:12px system-ui,sans-serif;white-space:nowrap;box-sizing:border-box}.version-bar button{display:flex;align-items:center;gap:6px;background:transparent;color:var(--text-dim);border:1px solid transparent;border-radius:6px;font:inherit;padding:4px 8px;cursor:pointer}.version-bar button.current{color:var(--accent);background:var(--accent-soft)}.version-bar button:hover{border-color:var(--border)}.version-bar button:active{background:var(--bg-sunken)}.version-bar button:focus-visible{outline:2px solid var(--focus);outline-offset:1px}.version-bar button:disabled{opacity:.5;cursor:default}.version-bar span{color:var(--text-dim)}.version-bar i{display:inline-block;width:6px;height:6px;background:currentColor;border-radius:50%}</style>
